#requires -Version 5.1
<# Created by Dewald Pretorius. Read-only SMB server and client security validator. #>
[CmdletBinding()]param([string]$OutputPath=(Join-Path ([Environment]::GetFolderPath('Desktop')) 'SMB_Security_Validation'))
$ErrorActionPreference='Stop';New-Item -ItemType Directory $OutputPath -Force|Out-Null;$s=Get-Date -Format yyyyMMdd_HHmmss
try{$server=Get-SmbServerConfiguration;$client=Get-SmbClientConfiguration;$result=[ordered]@{Generated=(Get-Date);Server=[ordered]@{EnableSMB1Protocol=$server.EnableSMB1Protocol;EnableSMB2Protocol=$server.EnableSMB2Protocol;RequireSecuritySignature=$server.RequireSecuritySignature;EnableSecuritySignature=$server.EnableSecuritySignature;EncryptData=$server.EncryptData};Client=[ordered]@{RequireSecuritySignature=$client.RequireSecuritySignature;EnableSecuritySignature=$client.EnableSecuritySignature;EnableInsecureGuestLogons=$client.EnableInsecureGuestLogons};Status='Healthy'};$warnings=@();if($server.EnableSMB1Protocol){$warnings+='SMB1 server protocol enabled'};if(-not$server.RequireSecuritySignature){$warnings+='Server signing not required'};if($client.EnableInsecureGuestLogons){$warnings+='Insecure guest logons enabled'};$result.Warnings=$warnings;if($warnings.Count){$result.Status='Warning'};$result|ConvertTo-Json -Depth 5|Set-Content (Join-Path $OutputPath "smb_security_$s.json");if($warnings.Count){exit 1};exit 0}catch{Write-Error $_;exit 5}
